def page(title, desc, h1, path, active="", content="", keyword="digital marketing agency", schema=None, noindex=False, eyebrow="", page_hero=True):
    canonical = ORIGIN + (path if path.endswith("/") else path + "/")
    title = SEO_TITLES.get(path, title)
    desc = SEO_DESCRIPTIONS.get(path, desc)
    crumbs = {"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":ORIGIN+"/"}]}
    if path != "/": crumbs["itemListElement"].append({"@type":"ListItem","position":2,"name":active or h1,"item":canonical})
    ld = [schema_org(), {"@context":"https://schema.org","@type":"WebSite","name":"ClearPath","url":ORIGIN}, crumbs]
    if schema: ld.append(schema)
    meta = '<meta name="robots" content="noindex,follow">' if noindex else '<meta name="robots" content="index,follow">'
    is_service_detail = path in {f"/services/{slug}/" for slug in SERVICE_WORKFLOWS}
    primary_cta = f'<div class="button-row"><a class="button button-primary" href="#service-enquiry">Get started with this service {svg("arrow")}</a><a class="text-link" href="/pricing/">View indicative pricing</a></div>' if is_service_detail else ""
    hero = f'''<section class="page-hero"><div class="container page-hero-inner"><div class="breadcrumb"><a href="/">Home</a><span>/</span><span>{escape(active or h1)}</span></div><p class="eyebrow">{eyebrow or f"ClearPath · {escape(active or 'Explore')}"}</p><h1>{h1}</h1><p class="lead">{desc}</p>{primary_cta}</div></section>''' if page_hero else ""
    return f'''<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0B1F3A">{meta}<title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}/assets/clearpath-social.svg"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)}"><meta name="twitter:description" content="{escape(desc)}"><meta name="twitter:image" content="{ORIGIN}/assets/clearpath-social.svg"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/icon-192.svg"><link rel="manifest" href="/manifest.webmanifest"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Sora:wght@600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">{json.dumps(ld,ensure_ascii=False)}</script></head><body>{header(active)}<main id="main">{hero}{content}</main>{footer()}<div id="react-app-root"></div><script type="module" src="/assets/app.js"></script></body></html>'''

def section(eyebrow, title, body="", inner="", cls=""):
    return f'<section class="section {cls}"><div class="container"><div class="section-heading"><p class="eyebrow">{eyebrow}</p><h2>{title}</h2>{f"<p class=\"lead\">{body}</p>" if body else ""}</div>{inner}</div></section>'

