def service_workflow(slug):
    workflow = SERVICE_WORKFLOWS[slug]
    steps = "".join(
        f'<li><h3>{title}</h3><p>{description}</p></li>'
        for title, description in workflow["steps"]
    )
    return f'''<section class="service-workflow" aria-labelledby="workflow-heading"><p class="eyebrow">HOW THE SERVICE RUNS</p><h2 id="workflow-heading">From agreed inputs to a working handover.</h2><p><strong>What we need to start:</strong> {workflow["inputs"]}</p><ol>{steps}</ol><div class="workflow-handover"><h3>What you receive</h3><p>{workflow["handover"]}</p></div></section>'''

