def service_enquiry_form(slug, service_name):
    intake = SERVICE_INTAKE[slug]
    fields = []
    for name, label, kind, options, required in intake["fields"]:
        field_id = f"service-{name}"
        required_attr = " required" if required else ""
        if kind == "select":
            choices = "".join(f'<option value="{escape(option)}">{escape(option)}</option>' for option in options)
            control = f'<select id="{field_id}" name="{name}"{required_attr}><option value="">Choose one</option>{choices}</select>'
        else:
            control = f'<input id="{field_id}" name="{name}" type="{kind}"{required_attr}>'
        fields.append(f'<div class="field"><label for="{field_id}">{escape(label)}{" *" if required else ""}</label>{control}</div>')
    return f'''<section class="section section-soft service-enquiry-section" id="service-enquiry" aria-labelledby="service-enquiry-heading"><div class="container service-enquiry-layout"><div class="service-enquiry-copy"><p class="eyebrow">READY TO GET STARTED?</p><h2 id="service-enquiry-heading">Tell us about your {escape(service_name.lower())} project.</h2><p>{escape(intake["intro"])} No payment is due now. We will review the details and confirm a suitable scope, fee and next steps before any work begins.</p><p>Our team will use your contact details only to respond to this enquiry. Please do not include passwords, payment details or other sensitive information.</p></div><form class="service-enquiry-form" name="service-enquiry" method="POST" action="/thank-you/" data-netlify="true" netlify-honeypot="bot-field"><input type="hidden" name="form-name" value="service-enquiry"><input type="hidden" name="service" value="{escape(service_name)}"><p class="honeypot"><label>Leave this field empty <input name="bot-field" tabindex="-1" autocomplete="off"></label></p><div class="field"><label for="service-name">Your name *</label><input id="service-name" name="name" autocomplete="name" required minlength="2"></div><div class="form-row"><div class="field"><label for="service-email">Email address *</label><input id="service-email" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="service-phone">Phone / WhatsApp *</label><input id="service-phone" name="phone" type="tel" autocomplete="tel" required></div></div><div class="field"><label for="service-business">Business name</label><input id="service-business" name="business_name" autocomplete="organization"></div>{''.join(fields)}<div class="field"><label for="service-requirements">{escape(intake["message"])} *</label><textarea id="service-requirements" name="requirements" rows="4" required minlength="10" placeholder="Share a few details so we can recommend the right next step."></textarea></div><label class="consent"><input type="checkbox" name="consent" value="yes" required><span>I agree that ClearPath may contact me about this service enquiry. See the <a href="/privacy/">Privacy Policy</a>. *</span></label><p class="form-error" data-form-error role="alert" aria-live="polite"></p><button class="button button-primary" type="submit">Send my service enquiry {svg("arrow")}</button><p class="tiny">We will review your request and get back to you shortly. Fees, timing and deliverables are confirmed before work starts.</p></form></div></section>'''

def service_pricing_cards():
    cards = "".join(
        f'''<article class="price-card"><p class="eyebrow">{name}</p><h3>{SERVICE_PRICING[slug]["range"]}</h3><p>{SERVICE_PRICING[slug]["cadence"]}</p><small>{SERVICE_PRICING[slug]["scope"]}</small><p><a class="text-link" href="/services/{slug}/#service-enquiry">Choose this service {svg("arrow")}</a></p></article>'''
        for name, _, _, slug, _ in services
    )
    return f'<div class="pricing-grid service-pricing-grid">{cards}</div>'

def service_cards():
    cards = "".join(f'<article class="service-card"><div class="icon-box">{svg(icon)}</div><p class="eyebrow">0{i+1} / SERVICE</p><h3>{name}</h3><p>{desc}</p>{service_rate(slug)}<a class="text-link" href="/services/{slug}/">Explore this service {svg("arrow")}</a><a class="text-link" href="/services/{slug}/#service-enquiry">Get started {svg("arrow")}</a></article>' for i,(name,desc,icon,slug,k) in enumerate(services))
    return f'<div class="service-grid">{cards}</div>'

def problem_cards():
    rows=[("01", "Marketing without measurement", "Clicks and impressions do not tell you which channels create real opportunities.", "We map the path from campaign to enquiry, agree the measures that matter, and report them in plain language."),("02", "Enquiries that wait too long", "A good lead can cool off when replies are delayed or follow-up is inconsistent.", "We improve the handoff and set up practical reminders or automations for your team."),("03", "Activity mistaken for progress", "More posts or a bigger budget do not automatically mean more customers.", "We prioritize the changes tied to conversion, revenue quality and customer fit.")]
    return '<div class="problem-grid">'+''.join(f'<article class="problem-card"><span>{n}</span><h3>{title}</h3><p>{body}</p><div class="fix"><b>How ClearPath helps</b><p>{fix}</p></div></article>' for n,title,body,fix in rows)+'</div>'

def process():
    steps=[("01","Discover","Understand your offer, audience, sales process and current numbers."),("02","Audit","Review the website, channels, tracking and enquiry experience."),("03","Build the foundation","Fix measurement, messaging and the pages customers need."),("04","Launch","Start focused campaigns and publish useful local or brand content."),("05","Optimize & report","Review lead quality, remove friction and agree the next action.")]
    return '<ol class="process-grid">'+''.join(f'<li><span>{num}</span><h3>{title}</h3><p>{body}</p></li>' for num,title,body in steps)+'</ol>'

